UPDATE UI_ALARM SET ALARM_NAME = #{alarmName}, ALARM_TYPE = #{alarmType}, ALARM_MAIL_YN = #{alarmMailYn}, ALARM_SMS_YN = #{alarmSmsYn}, ALARM_MONITOR_YN = #{alarmMonitorYn}, ALARM_CYCLE = #{alarmCycle}, ALARM_CYCLE_VAL = #{alarmCycleVal}, ALARM_WEEK = #{alarmWeek}, ALARM_TIME = #{alarmTime},
ALARM_TO = if(#{alarmTo} is null, null, xcnenc(#{encryptAlgorithm}, #{encryptSize}, #{encryptKey}, #{alarmTo})), ALARM_CC = if(#{alarmCC} is null, null, xcnenc(#{encryptAlgorithm}, #{encryptSize}, #{encryptKey}, #{alarmCC})),
ALARM_TO = #{alarmTo}, ALARM_CC = #{alarmCC},
ALARM_FORM_SEQ = #{alarmFormSeq}, ALARM_VAL = #{alarmVal}, USE_YN = #{useYn}, CSV_YN = #{csvYn}, EXCEL_MAX_CNT = #{excelMaxCnt} WHERE ALARM_SEQ = #{alarmSeq}
AND USER_ID = #{adminId}

UPDATE	UI_ALARM_FORM
SET		FORM_SUBJECT	= #{formSubject},
		FORM_CONTENT	= #{formContent},
		FORM_COMMENT	= #{formComment}
WHERE	FORM_SEQ	= #{formSeq}
